entries[55968] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an, verursacht 120% des normalen Waffenschadens. Zusätzlich stellen die nächsten 3 erfolgreichen Nahkampfangriffe 1% Gesundheit wieder her. Der Effekt hält 10 Sek. lang an." }
