entries[55972] = { ["name"] = "Monströse Stärke", ["text"] = "Sofort\nEure Fähigkeiten 'Blutstoß' und 'Auslöschen' haben eine Chance, 10 Sek. lang die Angriffskraft aller Schlachtzugsmitglieder innerhalb von 20 Metern um 10% zu erhöhen." }
entries[55973] = { ["name"] = "Blutseuche", ["text"] = "Nahkampfreichweite\nSofort\nEin bösartiger Schlag, der Waffenschaden verursacht, das Ziel verseucht und im Verlauf von 12 Sek. 2000 Schattenschaden hervorruft." }
entries[55974] = { ["name"] = "Siedendes Blut", ["text"] = "Sofort 15 sek. Abklingzeit\nVerursacht, dass alle Krankheitseffekte auf Zielen innerhalb von 30 Metern schmerzvoll ausbrechen und dabei 2250 bis 2750 Schaden verursachen (modifiziert durch Angriffskraft). Zwingt alle Ziele dazu, bis Abbruch lang den Todesritter anzugreifen." }
entries[55975] = { ["name"] = "Unheilige Raserei", ["text"] = "45 Meter Reichweite\nSofort\nVersetzt eine freundliche Einheit 8 Sek. lang in einen Blutrausch, erhöht ihren verursachten körperlichen Schaden um 40%, lässt sie jedoch pro Sekunde 1% ihrer maximalen Gesundheit verlieren." }
entries[55976] = { ["name"] = "Zauberabwehr", ["text"] = "Wirken in 1 sek.\nGreift in der Nähe befindliche Feinde mit einem Wirbel von Stahl an, der 6 Sek. lang anhält und alle 2 Sek. Waffenschaden verursacht. Verleiht dem Zaubernden zeitweilige Magie-Immunität." }
entries[55977] = { ["name"] = "Wirbelwind", ["text"] = "Sofort\nReflektiert Magie.\nVerursacht bei nahen Feinden alle 2 Sek. normalen Schaden." }
entries[55978] = { ["name"] = "Herzstoß", ["text"] = "-10 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nEin brutaler Angriff, der den Feind sofort schlägt und 150% Waffenschaden plus für jede auf das Ziel wirkende Krankheit zusätzlich 615 Schaden verursacht. Ziele dieses Angriffs können 10 Sek. lang keine Hasteffekte nutzen." }
entries[55980] = { ["name"] = "Mammuttrampeln", ["text"] = "Wirken in 0.25 sek. 4 sek. Abklingzeit\nVerursacht bei Feinden innerhalb von 10 Metern 5266 to 7734 Schaden." }
entries[55981] = { ["name"] = "Mammuttrompeten", ["text"] = "40 Meter Reichweite\nSofort 10 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, hat aber keinerlei Effekt, wenn das Ziel Euch bereits angreift." }
entries[55982] = { ["name"] = "Mammutsturmangriff", ["text"] = "5 - 30 Meter Reichweite\nWirken in 0.9 sek. 8 sek. Abklingzeit\nStürmt auf einen Gegner zu, verursacht normalen Schaden plus 2647 to 2953 und betäubt ihn 3 Sek. lang." }
